using attendence.Data;
using attendence.Models;
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using Microsoft.Data.SqlClient;
namespace attendence.Controllers;
[Authorize(Roles="Administrator")]
public sealed class SchoolManagementController(SchoolManagementRepository school,ILogger<SchoolManagementController> logger):Controller
{
 [HttpGet] public async Task<IActionResult> Index(CancellationToken ct){try{return View(await school.LoadAsync(ct));}catch(SqlException ex){logger.LogError(ex,"School directory query failed");TempData["Error"]="The school directory could not load. Check database setup.";return View(new SchoolManagementViewModel());}}
 [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> SaveDepartment([Bind(Prefix="Department")]DepartmentForm form,CancellationToken ct){if(!TryValidateModel(form,"Department"))return await Index(ct);try{await school.SaveDepartmentAsync(form,ct);TempData["Success"]="Department saved.";}catch(SqlException ex) when(ex.Number is 2601 or 2627){TempData["Error"]="Department names must be unique.";}catch(SqlException ex){logger.LogError(ex,"Department save failed");TempData["Error"]="Department could not be saved.";}return RedirectToAction(nameof(Index));}
 [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> SaveClass([Bind(Prefix="Class")]ClassForm form,CancellationToken ct){if(!TryValidateModel(form,"Class"))return await Index(ct);try{await school.SaveClassAsync(form,ct);TempData["Success"]="Class saved.";}catch(SqlException ex) when(ex.Number is 2601 or 2627){TempData["Error"]="That class name and academic year already exist in this department.";}catch(SqlException ex){logger.LogError(ex,"Class save failed");TempData["Error"]="Class could not be saved. Check that the department exists.";}return RedirectToAction(nameof(Index));}
 [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> SaveTeacher([Bind(Prefix="Teacher")]TeacherForm form,CancellationToken ct){if(!TryValidateModel(form,"Teacher"))return await Index(ct);try{await school.SaveTeacherAsync(form,ct);TempData["Success"]="Teacher saved.";}catch(SqlException ex) when(ex.Number is 2601 or 2627){TempData["Error"]="A teacher already uses that email.";}catch(SqlException ex){logger.LogError(ex,"Teacher save failed");TempData["Error"]="Teacher could not be saved.";}return RedirectToAction(nameof(Index));}
 [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> DeactivateTeacher(int id,CancellationToken ct){try{await school.DeactivateTeacherAsync(id,ct);TempData["Success"]="Teacher deactivated. Historical sessions remain intact.";}catch(SqlException ex){logger.LogError(ex,"Teacher deactivation failed");TempData["Error"]="Teacher could not be deactivated.";}return RedirectToAction(nameof(Index));}
 [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> SaveSubject([Bind(Prefix="Subject")]SubjectForm form,CancellationToken ct){if(!TryValidateModel(form,"Subject"))return await Index(ct);try{await school.SaveSubjectAsync(form,ct);TempData["Success"]="Subject and teacher assignment saved.";}catch(InvalidOperationException ex){TempData["Error"]=ex.Message;}catch(SqlException ex) when(ex.Number is 2601 or 2627){TempData["Error"]="Subject codes must be unique within each class.";}catch(SqlException ex){logger.LogError(ex,"Subject save failed");TempData["Error"]="Subject could not be saved. Verify the class and teacher.";}return RedirectToAction(nameof(Index));}
 [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> SaveSettings(SettingsForm form,CancellationToken ct){if(!ModelState.IsValid){TempData["Error"]="Enter an attendance threshold from 1 to 100 and a valid institution name.";return RedirectToAction(nameof(Index));}try{await school.SaveSettingsAsync(new SchoolManagementViewModel{LowAttendanceThreshold=form.LowAttendanceThreshold,InstitutionName=form.InstitutionName},ct);TempData["Success"]="Application settings saved.";}catch(SqlException ex){logger.LogError(ex,"Application settings save failed");TempData["Error"]="Settings could not be saved.";}return RedirectToAction(nameof(Index));}
}
